 49	    private static boolean isComponentBipartite(
 50	            int startVertex,
 51	            List<List<Integer>> adjacencyList,
 52	            int[] colors) {
 53	        Deque<Integer> queue = new ArrayDeque<>();
 54	        colors[startVertex] = FIRST_COLOR;
 55	        queue.offer(startVertex);
 56	
 57	        while (!queue.isEmpty()) {
 58	            int currentVertex = queue.poll();
 59	
 60	            for (int neighbor : adjacencyList.get(currentVertex)) {
 61	                if (colors[neighbor] == UNCOLORED) {
 62	                    colors[neighbor] = oppositeColor(colors[currentVertex]);
 63	                    queue.offer(neighbor);
 64	                    continue;
 65	                }
 66	
 67	                if (colors[neighbor] == colors[currentVertex]) {
 68	                    return false;
 69	                }
 70	            }
 71	        }
 72	
 73	        return true;
 74	    }
